import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4]
pack=ROOT/'packages/story-candidate-02/assets/final-scifi-v1'
ref=str(pack/'masters/terrain/terrain-board-02.png')
style=str(pack/'masters/approved-v5/canonical-terrain/farlight-cargo-hold/master.png')
subjects={
'nereia-deep-water':('third','Deep dark petrol-blue ocean water with large calm turquoise curved water planes, sparse broad subdued submerged stone silhouettes, and a few heavy teal wave contours. Preserve dark deep-water identity. No exposed rocks, reefs, banks, islands or structures.'),
'nereia-floating-platform':('first','Warm ivory stone-metal floating platform DECK surface, broad cream inset paving panels, heavy charcoal and antique brass mechanical seams and sparse large cyan circular utility inset caps. Preserve the original warm pale platform material with brass and turquoise engineering accents. Flatten the deck into an overhead surface that fills every pixel; no ocean border, pillars, bridges or perspective scene.'),
'nereia-reverse-current':('fourth','Strong opposing reverse ocean currents in deep turquoise water, two broad curling S-shaped streams of pale cyan foam, a bold readable central countercurl and darker teal separation bands. Preserve fast turbulent water identity, not arrows. Use only a handful of very broad flat-color foam ribbons and chunky curved water planes, not froth speckles. No exposed rocks, shore, coral or obstacles.'),
'nereia-shallow-tide':('second','Shallow luminous aquamarine tidal water over pale sand, broad warm mint sandbar planes below transparent-looking but fully opaque turquoise water, a few very broad pale-cyan tidal wave contours and sparse low-contrast submerged teal stone silhouettes. Preserve light shallow-water identity, distinctly brighter than deep ocean. No exposed rocks, coral, plants, shore or obstacles.')}
requests=[]
for slug,(col,subject) in subjects.items():
 d=pack/'masters/approved-v5/canonical-terrain'/slug; d.mkdir(exist_ok=False)
 comp=('Exactly four equally sized square material variants in a precise 2-by-2 arrangement filling the square canvas. Each quadrant is an independent overhead square, equal scale, no gutters, frames or labels. Sampled whole in top-left, top-right, bottom-left, bottom-right order.' if slug.endswith('floating-platform') else 'Exactly one square continuous material, not a sheet and not multiple variants. Essential broad motif must remain legible within central 40 percent and four cardinal middle-quarter strips for historical NESW masking.')
 prompt=f'Use case: stylized-concept. Create ONE independently authored game terrain material master for c02-terrain-{slug}. Input image 1 is subject reference ONLY: use its top row {col} column, ignore all seven other subjects. Input image 2 is STYLE ONLY: chunky matte hand-painted tactical RPG science-fiction language, bold dark contour lines, exaggerated broad planes, restrained two-step cel shading. Do not copy cargo motifs or metal into water. Subject: {subject} Composition: strictly flat orthographic overhead ground or water material, no perspective. {comp} Every pixel opaque; material extends to every edge. Simplify aggressively for 32px logical tile readability. No text, symbols, arrows, labels, gridlines, borders, blank margins, tiny speckles, excessive microtexture, glossy 3D, photographic detail or scene framing.'
 req={'prompt':prompt,'referenced_image_paths':[ref,style],'transparent_background':False}
 (d/'prompt.txt').write_text(prompt);(d/'request.json').write_text(json.dumps(req,indent=2)); requests.append({'slug':slug,**req})
(Path(__file__).parent/'reservation.json').write_text(json.dumps({'topics':['c02-terrain-'+s for s in subjects],'reason':'Next uncompleted manifest-order C02 family after Milight. Original builder top row board 02 maps floating-platform, shallow-tide, deep-water, reverse-current at indices 8-11; original topic source absent, mapping corroborated by full board and runtime subjects.','requests':requests},indent=2))
